 private List<org.json.JSONObject> trashRecords(List<MediaRepository.Item> list){List<org.json.JSONObject> rows=new ArrayList<>();for(MediaRepository.Item item:list)if(item.trashRecord!=null)rows.add(item.trashRecord);return rows;}
 private void restoreTrashItems(List<MediaRepository.Item> list){List<org.json.JSONObject> rows=trashRecords(list);if(rows.isEmpty())return;new MenuDialog(this).setTitle("Restore "+rows.size()+" item(s)?").setMessage("Return these files to their original location.").setNegativeButton("Cancel",null).setPositiveButton("Restore",(d,n)->{pendingUi=null;restoreRecords(rows);}).show();}
 private void confirmPurge(List<MediaRepository.Item> list){List<org.json.JSONObject> rows=trashRecords(list);if(rows.isEmpty()||!unlockedRecords(rows))return;new MenuDialog(this).setTitle("Permanently delete "+rows.size()+" item(s)?").setMessage("These files cannot be restored afterward.").setNegativeButton("Cancel",null).setPositiveButton("Delete permanently",(d,n)->{pendingUi=null;List<Uri> nativeUris=new ArrayList<>();for(org.json.JSONObject o:rows)if(o.optString("type").equals("native"))nativeUris.add(Uri.parse(o.optString("uri")));if(!nativeUris.isEmpty()&&Build.VERSION.SDK_INT>=30){pendingPurges=rows;try{startIntentSenderForResult(MediaStore.createDeleteRequest(getContentResolver(),nativeUris).getIntentSender(),49,null,0,0,0);}catch(Exception e){pendingPurges=Collections.emptyList();toast("Android could not request deletion");}}else finishPurge(rows);}).show();}
 private void finishPurge(List<org.json.JSONObject> rows){pendingUi=null;io.execute(()->{int completed=0;String error="";for(org.json.JSONObject o:rows)try{if(o.optString("type").equals("native"))files.markExpired(o);else files.purge(o);completed++;}catch(Exception e){error=e.getMessage();}int done=completed;String problem=error;runOnUiThread(()->{resumeUri=null;thumbs.clear();images.clear();reload();toast(done+" permanently deleted"+(problem.isEmpty()?"":" · "+problem));});});}
