 private void removeExplorerFolder(MediaRepository.Item item){
  if(locks.locked(item.key)&&!admin){password(false,()->removeExplorerFolder(item));return;}
  new MenuDialog(this).setTitle("Remove from Explorer?").setMessage("Remove "+item.name+" from added locations? The original folder and its files will not be deleted. Existing locks will be kept.")
   .setNegativeButton("Cancel",null).setPositiveButton("Remove",(d,n)->{
    if(locks.locked(item.key)&&!admin){toast("Unlock Admin mode first");return;}
    try{
     if(ArchiveStore.virtual(item.uri)){archives.removeLocation(item.uri);}else{
      Uri tree=DocumentsContract.buildTreeDocumentUri(item.uri.getAuthority(),DocumentsContract.getTreeDocumentId(item.uri));
      for(UriPermission grant:getContentResolver().getPersistedUriPermissions())if(grant.getUri().equals(tree)){
       int flags=(grant.isReadPermission()?Intent.FLAG_GRANT_READ_URI_PERMISSION:0)|(grant.isWritePermission()?Intent.FLAG_GRANT_WRITE_URI_PERMISSION:0);
       getContentResolver().releasePersistableUriPermission(tree,flags);
      }
     }
     Set<String> favorites=settings.set("favorites");favorites.remove(item.identity());favorites.remove(item.key);
     settings.p.edit().putStringSet("favorites",favorites).remove("favoriteFolder:"+item.key).apply();
     route=null;history.clear();resumeUri=null;savedScroll=0;thumbs.clear();images.clear();reload();
    }catch(Exception e){toast("Could not remove folder access. Please try again.");}
   }).show();
 }
