 private void folderRules(boolean include){io.execute(()->{List<MediaRepository.Item> all=media.albums(locks,admin,false);all.addAll(media.roots());runOnUiThread(()->{if(!active)return;String key=include?"included":"excluded";Set<String> current=settings.set(key);List<String> ids=new ArrayList<>(),names=new ArrayList<>();for(MediaRepository.Item i:all)if(!ids.contains(i.key)){ids.add(i.key);names.add(i.name+"\n"+i.path);}for(String id:current)if(!ids.contains(id)){ids.add(id);names.add(id);}LinearLayout choices=new LinearLayout(this);choices.setOrientation(1);choices.setPadding(dp(16),0,dp(16),0);for(int n=0;n<ids.size();n++){final String id=ids.get(n);CheckBox box=new CheckBox(this);box.setText(names.get(n));box.setTextSize(12);box.setTextColor(UiTheme.text);box.setPadding(dp(4),dp(7),dp(4),dp(7));box.setMinHeight(dp(48));box.setChecked(current.contains(id));box.setOnCheckedChangeListener((v,on)->settings.toggle(key,id));choices.addView(box,new LinearLayout.LayoutParams(-1,-2));}ScrollView scroll=new ScrollView(this);scroll.addView(choices);TextView heading=text(include?"Included Folders":"Excluded Folders",22,UiTheme.text);heading.setTypeface(null,Typeface.BOLD);heading.setPadding(dp(20),dp(16),dp(20),dp(12));new MenuDialog(this).setCustomTitle(heading).setView(scroll).setPositiveButton("Done",(d,n)->reload()).setNeutralButton("Add location",(d,n)->pickFolder()).show();});});}
 private void folderPermissions(){List<UriPermission> grants=getContentResolver().getPersistedUriPermissions();String[] names=new String[grants.size()+1];names[0]="Add folder access";for(int n=0;n<grants.size();n++)names[n+1]=grants.get(n).getUri().toString();new MenuDialog(this).setTitle("Folder permissions").setItems(names,(d,n)->{if(n==0){pickFolder();return;}UriPermission permission=grants.get(n-1);new MenuDialog(this).setTitle("Revoke folder access?").setMessage(permission.getUri().toString()).setNegativeButton("Cancel",null).setPositiveButton("Revoke",(a,b)->{getContentResolver().releasePersistableUriPermission(permission.getUri(),(permission.isReadPermission()?Intent.FLAG_GRANT_READ_URI_PERMISSION:0)|(permission.isWritePermission()?Intent.FLAG_GRANT_WRITE_URI_PERMISSION:0));route=null;reload();}).show();}).show();}
