 private boolean archiveReadOnly(List<MediaRepository.Item> list){for(MediaRepository.Item i:list)if(i.archive){toast("ZIP entries are browse-only. Extract them with a file manager to edit, share or copy.");return true;}return false;}
 private boolean preparingShare;
 private boolean shareVideo(MediaRepository.Item item){
  if(item.video||item.mime!=null&&item.mime.startsWith("video/"))return true;
  String n=item.name==null?"":item.name.toLowerCase(java.util.Locale.ROOT);
  return n.endsWith(".mp4")||n.endsWith(".mov")||n.endsWith(".mkv")||n.endsWith(".webm")||n.endsWith(".3gp");
 }
 private String shareMime(MediaRepository.Item item){
  String mime=null;
  try{mime=getContentResolver().getType(item.uri);}catch(Exception ignored){}
  if(mime==null||mime.equals("application/octet-stream"))mime=item.mime;
  String name=item.name==null?"":item.name.toLowerCase(java.util.Locale.ROOT);
  if(shareVideo(item)){
   if(name.endsWith(".mp4"))return "video/mp4";
   if(name.endsWith(".webm"))return "video/webm";
   if(name.endsWith(".3gp"))return "video/3gpp";
   if(name.endsWith(".mkv"))return "video/x-matroska";
   if(name.endsWith(".mov"))return "video/quicktime";
   return mime!=null&&mime.startsWith("video/")?mime:"video/*";
  }
  return mime==null||mime.isEmpty()?"application/octet-stream":mime;
 }
 private void share(List<MediaRepository.Item> list){
  if(tab==4||list.isEmpty()||archiveReadOnly(list)||preparingShare)return;
  List<MediaRepository.Item> source=new ArrayList<>(list);
  preparingShare=true;
  io.execute(()->{
   ArrayList<Uri> uris=new ArrayList<>();String problem=null;
   try{
    for(MediaRepository.Item item:source){
     if(item.uri==null)throw new IOException("Media URI is unavailable");
     // Converted MediaStore/document videos are shared directly with read grants.
     // Copy only files with non-content URIs or a provider that cannot expose the media.
     Uri uri=item.uri;
     if(shareVideo(item)||!"content".equalsIgnoreCase(uri.getScheme())){
      uri=ShareProvider.stage(this,uri,item.name==null?"shared-media":item.name,shareMime(item));
     }
     uris.add(uri);
    }
   }catch(Exception e){android.util.Log.e("GalleryFlow","Share media preparation failed",e);problem=e.getMessage();}
   final String error=problem;
   runOnUiThread(()->{
    preparingShare=false;
    if(!active)return;
    if(error!=null||uris.size()!=source.size()){toast("Cannot prepare media for sharing"+(error==null?".":": "+error));return;}
    sendShare(source,uris);
   });
  });
 }
 private void sendShare(List<MediaRepository.Item> list,ArrayList<Uri> uris){
  if(uris.isEmpty())return;
  String mime=list.size()==1?shareMime(list.get(0)):list.stream().allMatch(this::shareVideo)?"video/*":list.stream().noneMatch(i->shareVideo(i)||i.generic)?"image/*":"*/*";
  Intent intent=new Intent(uris.size()==1?Intent.ACTION_SEND:Intent.ACTION_SEND_MULTIPLE).setType(mime);
  ClipData clip=new ClipData("Shared media",new String[]{mime},new ClipData.Item(uris.get(0)));
  for(int n=1;n<uris.size();n++)clip.addItem(new ClipData.Item(uris.get(n)));
  if(uris.size()==1)intent.putExtra(Intent.EXTRA_STREAM,uris.get(0));else intent.putParcelableArrayListExtra(Intent.EXTRA_STREAM,uris);
  intent.setClipData(clip);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
  Intent chooser=Intent.createChooser(intent,"Share media");chooser.setClipData(clip);chooser.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
  try{startActivity(chooser);}catch(Exception e){android.util.Log.e("GalleryFlow","Sharing failed",e);toast("Sharing failed: "+e.getClass().getSimpleName());}
 }

 private void details(List<MediaRepository.Item> list){if(list.isEmpty())return;long bytes=0;StringBuilder b=new StringBuilder();for(MediaRepository.Item i:list){bytes+=i.size;if(list.size()<=5)b.append(i.name).append("\n").append(i.path).append("\n").append(i.mime).append(" · ").append(android.text.format.Formatter.formatFileSize(this,i.size)).append("\n").append(i.date>0?java.text.DateFormat.getDateTimeInstance().format(new Date(i.date)):"").append("\n\n");}if(list.size()>5)b.append(list.size()).append(" items\n");b.append("Total: ").append(android.text.format.Formatter.formatFileSize(this,bytes));new MenuDialog(this).setTitle("Information").setMessage(b.toString()).setPositiveButton("Close",null).show();}
 private void editCurrent(){if(tab==4)return;if(photoIndex<0||loadingMedia||archiveReadOnly(Collections.singletonList(items.get(photoIndex))))return;MediaRepository.Item i=items.get(photoIndex);Intent intent=new Intent(Intent.ACTION_EDIT).setDataAndType(i.uri,i.mime).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);if(i.document)intent.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION);intent.putExtra("finishActivityOnSaveCompleted",true);launch(Intent.createChooser(intent,"Edit media"));}
 private void copy(List<MediaRepository.Item> list){if(list.isEmpty()||archiveReadOnly(list)){pendingMove=false;return;}pendingCopies=new ArrayList<>(list);try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION),43);}catch(ActivityNotFoundException e){pendingCopies=Collections.emptyList();pendingMove=false;toast("Folder picker unavailable");}}
 private void move(List<MediaRepository.Item> list){pendingMove=true;copy(list);}
 private void doCopy(Uri tree){List<MediaRepository.Item> source=new ArrayList<>(pendingCopies);boolean moving=pendingMove;pendingMove=false;pendingCopies=Collections.emptyList();String batch=UUID.randomUUID().toString();try{getContentResolver().takePersistableUriPermission(tree,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}catch(Exception ignored){}io.execute(()->{List<MediaRepository.Item> copied=new ArrayList<>();String error="";Uri parent=DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));for(MediaRepository.Item i:source){try{files.copy(i,parent,batch);copied.add(i);}catch(Exception e){error=e.getMessage();}}String problem=error;runOnUiThread(()->{if(moving&&!copied.isEmpty()){if(!problem.isEmpty())toast(copied.size()+" of "+source.size()+" copied; remaining originals kept · "+problem);trashItems(copied,batch);}else{toast(copied.size()+" copied. Undo is in Settings & tools."+(problem.isEmpty()?"":" · "+problem));reload();}});});}
 private void delete(List<MediaRepository.Item> list){if(tab==4){confirmPurge(list);return;}if(list.isEmpty()||archiveReadOnly(list))return;if(photoIndex>=0&&loadingMedia){toast("Please wait for this image to load");return;}stopSlideshow();List<MediaRepository.Item> safe=new ArrayList<>(list);Runnable operation=()->performDelete(safe);if(settings.bool("confirmDelete",true))new MenuDialog(this).setTitle("Move "+list.size()+" item(s) to Trash?").setMessage("Keep in Trash for "+settings.num("trashDays",30)+" days, or delete permanently from the Trash tab. Android may require confirmation or apply its own expiry.").setNegativeButton("Cancel",null).setPositiveButton("Move to Trash",(d,n)->operation.run()).show();else operation.run();}
 private void performDelete(List<MediaRepository.Item> list){trashItems(list,UUID.randomUUID().toString());}
 private void trashItems(List<MediaRepository.Item> list,String batch){List<MediaRepository.Item> nativeItems=new ArrayList<>(),local=new ArrayList<>();for(MediaRepository.Item i:list){if("media".equals(i.uri.getAuthority())&&Build.VERSION.SDK_INT>=30)nativeItems.add(i);else local.add(i);}io.execute(()->{String error="";for(MediaRepository.Item i:local)try{files.trashDocument(i,batch);}catch(Exception e){error=e.getMessage();}String problem=error;runOnUiThread(()->{if(!problem.isEmpty())toast(problem);if(!nativeItems.isEmpty()){pendingTrash=nativeItems;trashBatch=batch;try{List<Uri> uris=new ArrayList<>();for(MediaRepository.Item i:nativeItems)uris.add(i.uri);startIntentSenderForResult(MediaStore.createTrashRequest(getContentResolver(),uris,true).getIntentSender(),47,null,0,0,0);}catch(Exception e){toast("Could not request Trash; originals were kept.");}}else{resumeUri=null;reload();toast("File operation completed. Undo is in Settings & tools.");}});});}
 private void dateGroups(){new MenuDialog(this).setTitle("Date separators").setItems(new String[]{"Month","Week","Day","None"},(d,n)->{settings.put("months",n!=3);if(n<3)settings.put("dateGroup",new String[]{"Month","Week","Day"}[n]);reload();}).show();}
 private boolean unlockedRecords(List<org.json.JSONObject> rows){for(org.json.JSONObject o:rows)if(locks.locked(o.optString("key"))&&!admin){toast("Unlock Admin mode to access these files.");return false;}return true;}
 private void undoLast(){List<org.json.JSONObject> rows=files.latest();if(rows.isEmpty()){toast("Nothing to undo");return;}if(!unlockedRecords(rows))return;new MenuDialog(this).setTitle("Undo last file operation?").setMessage("Restore trashed originals and remove unchanged copies created by that operation.").setNegativeButton("Cancel",null).setPositiveButton("Undo",(d,n)->restoreRecords(rows)).show();}
 private void restoreRecords(List<org.json.JSONObject> rows){if(!unlockedRecords(rows))return;for(org.json.JSONObject o:rows)if(o.optString("type").equals("expired")){toast("Original was permanently deleted or expired. Copies were kept.");return;}List<Uri> nativeUris=new ArrayList<>();for(org.json.JSONObject o:rows)if(o.optString("type").equals("native"))nativeUris.add(Uri.parse(o.optString("uri")));if(!nativeUris.isEmpty()&&Build.VERSION.SDK_INT>=30){pendingUndo=rows;try{startIntentSenderForResult(MediaStore.createTrashRequest(getContentResolver(),nativeUris,false).getIntentSender(),48,null,0,0,0);}catch(Exception e){toast("Cannot restore these originals; copies have been kept.");}return;}finishUndo(rows);}
 private void finishUndo(List<org.json.JSONObject> rows){pendingUi=null;io.execute(()->{String error="";try{for(org.json.JSONObject o:rows)if(!o.optString("type").equals("copy")){if(o.optString("type").equals("native"))files.remove(o);else files.undoLocal(o);}for(org.json.JSONObject o:rows)if(o.optString("type").equals("copy"))files.undoLocal(o);}catch(Exception e){error=e.getMessage();}String problem=error;runOnUiThread(()->{pendingUi=null;resumeUri=null;thumbs.clear();images.clear();reload();toast(problem.isEmpty()?"Restored / undone":problem);});});}
 private void showTrash(){List<org.json.JSONObject> rows=files.trash();rows.removeIf(o->locks.locked(o.optString("key"))&&!admin);if(rows.isEmpty()){toast("Trash is empty");return;}String[] names=new String[rows.size()];for(int n=0;n<names.length;n++){org.json.JSONObject o=rows.get(n);long days=Math.max(0,(o.optLong("expires",o.optLong("time")+FileActions.RETENTION)-System.currentTimeMillis()+86399999)/86400000);names[n]=o.optString("name")+" · "+days+" days remaining";}new MenuDialog(this).setTitle("Trash · restore within 30 days").setItems(names,(d,n)->{org.json.JSONObject o=rows.get(n);new MenuDialog(this).setTitle(o.optString("name")).setItems(new String[]{"Restore","Delete permanently"},(a,k)->{if(k==0)restoreRecords(Collections.singletonList(o));else new MenuDialog(this).setTitle("Delete permanently?").setMessage("This cannot be undone.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(b,v)->purgeTrash(o)).show();}).show();}).setNegativeButton("Close",null).show();}
 private void purgeTrash(org.json.JSONObject o){if(!unlockedRecords(Collections.singletonList(o)))return;if(o.optString("type").equals("native")&&Build.VERSION.SDK_INT>=30){pendingPurge=o;try{startIntentSenderForResult(MediaStore.createDeleteRequest(getContentResolver(),Collections.singletonList(Uri.parse(o.optString("uri")))).getIntentSender(),49,null,0,0,0);}catch(Exception e){toast("Android could not delete this item");}}else io.execute(()->{try{files.purge(o);runOnUiThread(()->toast("Permanently deleted"));}catch(Exception e){runOnUiThread(()->toast("Could not delete"));}});}
 protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==50){externalVideoLaunched=false;externalReturn=true;return;}if(r==46&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri source=data.getData();try{getContentResolver().takePersistableUriPermission(source,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}String name="Archive.zip";try(android.database.Cursor c=getContentResolver().query(source,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}catch(Exception ignored){}String key;try{key=LockStore.canonical(source);}catch(Exception e){key="zip:"+ArchiveStore.hash(source.toString());}MediaRepository.Item item=new MediaRepository.Item(source,name,key,true,1);item.zip=true;item.document=true;resumeUri=null;pendingZip=item;if(active){pendingZip=null;openArchive(item);}}else if(r==42&&result==RESULT_OK&&data!=null&&data.getData()!=null){try{getContentResolver().takePersistableUriPermission(data.getData(),data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));pendingUi=null;tab=2;route=null;history.clear();resumeUri=null;}catch(Exception e){toast("Could not retain folder permission");}reload();}else if(r==43){if(result==RESULT_OK&&data!=null&&data.getData()!=null)doCopy(data.getData());else{pendingCopies=Collections.emptyList();pendingMove=false;}}else if(r==47){if(result==RESULT_OK){try{for(MediaRepository.Item i:pendingTrash)files.nativeTrash(i,trashBatch);}catch(Exception e){toast("Trash journal could not be saved");}pendingUi=null;resumeUri=null;toast("Moved to Trash. Undo is in Settings & tools.");}else toast("Trash canceled; originals kept. Any completed copies can be undone.");pendingTrash=Collections.emptyList();reload();}else if(r==48){if(result==RESULT_OK)finishUndo(pendingUndo);pendingUndo=Collections.emptyList();}else if(r==49){if(result==RESULT_OK){if(!pendingPurges.isEmpty())finishPurge(pendingPurges);else if(pendingPurge!=null)finishPurge(Collections.singletonList(pendingPurge));}pendingPurge=null;pendingPurges=Collections.emptyList();}}

 private void toggleLock(String key,String name){if(!admin)return;locks.setLocked(key,name,!locks.keys().contains(key));thumbs.clear();images.clear();reload();}
 private void back(){pendingUi=null;photoRestore=null;if(browsing&&route==null){pendingUi=null;cancelBrowse();loading(false,"");if(uiLoaded){controls();return;}if(tab!=1){switchTab(1);return;}super.onBackPressed();return;}if(infoOverlay!=null){dismissInfo(true);return;}if(photoIndex>=0){if(fullscreen)setFullscreen(false);else exitViewer(true);return;}if(selectionMode){selectionMode=false;selected.clear();if(gallery!=null){gallery.setSelection(selected);gallery.setSelectionMode(false);}controls();return;}if(route!=null){explorerBack();return;}if(tab!=1){rememberGallery();tab=1;savedScroll=0;reload();return;}super.onBackPressed();}
 @Override public void onBackPressed(){back();}
 private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}

 private void endAdmin(){
  if(!admin)return;
  admin=false;ArchiveStore.admin=false;authGeneration++;thumbs.clear();images.clear();
  if(adminButton!=null)adminButton.setChecked(false);
  getWindow().clearFlags(WindowManager.LayoutParams.FLAG_SECURE);reload();
 }
    private void adminMenu(){
        if(!admin){password(!locks.configured(),this::reload);return;}
        new MenuDialog(this).setTitle("Admin mode").setItems(new String[]{"Manage locked folders","Change password","Exit Admin and relock","About folder protection"},(d,n)->{
            if(n==0)manageLocks();else if(n==1)password(true,()->toast("Password changed"));else if(n==2)endAdmin();else protectionInfo();
        }).show();
    }
    private void protectionInfo(){new MenuDialog(this).setTitle("Folder protection").setMessage("Locks hide photos in Gallery Flow and require the administrator password to open folders here. Locks include subfolders and relock as soon as you leave the app.\n\nOriginal files are not encrypted. Other apps, USB access, uninstalling or clearing app data can bypass these locks. There is no password recovery.\n\nAndroid blocks access to protected system and other apps’ private folders. Cloud providers may expose the same files under different identifiers; lock each provider location separately.").setPositiveButton("Got it",null).show();}
    private void manageLocks(){
        List<String> keys=new ArrayList<>(locks.keys());Collections.sort(keys);if(keys.isEmpty()){toast("Open a folder and tap Lock, or hold a folder tile.");return;}
        String[] names=new String[keys.size()];for(int i=0;i<names.length;i++)names[i]=locks.label(keys.get(i))+"\n"+keys.get(i);
        new MenuDialog(this).setTitle("Locked folders · tap to remove").setItems(names,(d,n)->{if(!admin)return;new MenuDialog(this).setTitle("Remove this lock?").setMessage(names[n]).setNegativeButton("Cancel",null).setPositiveButton("Remove lock",(a,b)->{if(admin){locks.setLocked(keys.get(n),locks.label(keys.get(n)),false);thumbs.clear();images.clear();reload();}}).show();}).setNegativeButton("Done",null).show();
    }
    private void password(boolean setup,Runnable after){
        if(!setup&&locks.waitSeconds()>0){toast("Try again in "+locks.waitSeconds()+" seconds.");return;}
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(24),dp(8),dp(24),dp(8));
        TextView info=text(setup?"Use at least 4 characters. This password protects folders inside Gallery Flow; original files are not encrypted.":"Enter your password to access locked folders and manage their locks.",14,MUTED);form.addView(info);
        EditText pass=new EditText(this);pass.setSingleLine(true);pass.setHint("Password");pass.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);pass.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);form.addView(pass);
        EditText confirm=new EditText(this);confirm.setSingleLine(true);confirm.setHint("Confirm password");confirm.setInputType(pass.getInputType());confirm.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);if(setup)form.addView(confirm);
        TextView error=text("",13,0xffff8981);form.addView(error);
        AlertDialog dialog=new MenuDialog(this).setTitle(setup?"Set administrator password":"Unlock Admin mode").setView(form).setNegativeButton("Cancel",null).setPositiveButton(setup?"Save password":"Unlock",null).create();passwordDialog=dialog;
        dialog.getWindow();dialog.setOnShowListener(unused->{dialog.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{
            String value=pass.getText().toString();if(setup&&(value.length()<4||!value.equals(confirm.getText().toString()))){error.setText("Use 4+ characters and matching passwords.");return;}
            final char[] secret=value.toCharArray();final int token=authGeneration;dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(false);error.setText("Checking…");
            auth.execute(()->{boolean ok=false;String failure="Incorrect password.";try{if(setup){locks.setup(secret);ok=true;}else ok=locks.verify(secret);if(locks.waitSeconds()>0)failure="Try again in "+locks.waitSeconds()+" seconds.";}catch(Exception e){failure="Password operation failed. Please try again.";}finally{Arrays.fill(secret,'\0');}final boolean accepted=ok;final String message=failure;runOnUiThread(()->{if(token!=authGeneration||!active||!dialog.isShowing())return;dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(true);pass.setText("");confirm.setText("");if(!accepted){error.setText(message);return;}admin=true;ArchiveStore.admin=true;adminButton.setChecked(true);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);dialog.dismiss();after.run();});});
        });});dialog.show();
    }

